import { HoverCard } from '@absoluteui/components/hover-card';

const link = document.querySelector<HTMLAnchorElement>('a[href="/u/ada"]');
if (link) {
  const content = document.createElement('div');
  const name = document.createElement('p');
  name.textContent = 'Ada Lovelace';
  const role = document.createElement('p');
  role.textContent = 'Mathematician, London';
  content.append(name, role);
  HoverCard.create(link, { content, placement: 'bottom-start' });
}

import { HoverCard, type HoverCardCloseDetail } from '@absoluteui/components/hover-card';
import { Button } from '@absoluteui/components/button';

const trigger = document.createElement('a');
trigger.href = '/repos/atlas';
trigger.textContent = 'atlas';
document.body.append(trigger);

const content = document.createElement('div');
const summary = document.createElement('p');
summary.textContent = 'Mapping toolkit. 1.2k stars.';
const star = document.createElement('button');
star.type = 'button';
star.textContent = 'Star';
Button.enhance(star, { size: 'sm' });
content.append(summary, star);

// Tab moves from the trigger into the card, so the Star button is keyboard reachable.
const card = HoverCard.create(trigger, { content, describe: false, showDelay: 400, hideDelay: 400 });
card.element.addEventListener('aui-close', (event) => {
  const { reason } = (event as CustomEvent<HoverCardCloseDetail>).detail;
  trigger.dataset.cardClosed = reason;
});
